import subprocess
import sys
import unittest


def run(*args):
    return subprocess.run([sys.executable, "report.py", *args, "data/sample.csv"], capture_output=True, text=True, check=True).stdout


class ReportTest(unittest.TestCase):
    def test_month(self):
        self.assertEqual(run("--month", "2026-10"), "合計: 3260 円\n")

    def test_top(self):
        self.assertEqual(run("--top", "1"), "合計: 2400 円\n")
